type EventCallback = (payload: any) => void;

class EventBus {
    private subscribers: Map<string, EventCallback[]>;

    constructor() {
        this.subscribers = new Map();
    }

    /**
     * Publishes an event to all subscribed listeners.
     * @param event The name of the event to publish.
     * @param payload The data associated with the event.
     */
    publish(event: string, payload: any): void {
        const callbacks = this.subscribers.get(event);
        if (callbacks) {
            callbacks.forEach(callback => {
                try {
                    callback(payload);
                } catch (error) {
                    console.error(`Error in event subscriber for event "${event}":`, error);
                }
            });
        }
    }

    /**
     * Subscribes a callback function to an event.
     * @param event The name of the event to subscribe to.
     * @param callback The function to call when the event is published.
     */
    subscribe(event: string, callback: EventCallback): void {
        if (!this.subscribers.has(event)) {
            this.subscribers.set(event, []);
        }
        this.subscribers.get(event)!.push(callback);
    }
}

export const eventBus = new EventBus();

import { randomUUID } from 'crypto';

export interface User {
    id: string;
    name: string;
    email: string;
}

class UserService {
    private users: Map<string, User>;

    constructor() {
        this.users = new Map();
    }

    /**
     * Creates a new user.
     * @param name The name of the user.
     * @param email The email of the user.
     * @returns The created user.
     */
    create(name: string, email: string): User {
        if (!name || !email) {
            throw new Error('Name and email are required.');
        }
        const id = randomUUID();
        const newUser: User = { id, name, email };
        this.users.set(id, newUser);
        return newUser;
    }

    /**
     * Retrieves a user by their ID.
     * @param id The ID of the user.
     * @returns The user, or undefined if not found.
     */
    getById(id: string): User | undefined {
        return this.users.get(id);
    }

    /**
     * Retrieves all users.
     * @returns An array of all users.
     */
    getAll(): User[] {
        return Array.from(this.users.values());
    }

    /**
     * Updates an existing user.
     * @param id The ID of the user to update.
     * @param updates An object containing the fields to update (name, email).
     * @returns The updated user, or undefined if the user was not found.
     */
    update(id: string, updates: { name?: string; email?: string }): User | undefined {
        const user = this.users.get(id);
        if (user) {
            if (updates.name !== undefined) user.name = updates.name;
            if (updates.email !== undefined) user.email = updates.email;
            this.users.set(id, user); // Re-set to ensure Map updates if value is mutated directly
            return user;
        }
        return undefined;
    }

    /**
     * Deletes a user by their ID.
     * @param id The ID of the user to delete.
     * @returns True if the user was deleted, false otherwise.
     */
    delete(id: string): boolean {
        return this.users.delete(id);
    }
}

export const userService = new UserService();

import { randomUUID } from 'crypto';

export interface Project {
    id: string;
    name: string;
    description: string;
    memberIds: string[];
}

class ProjectService {
    private projects: Map<string, Project>;

    constructor() {
        this.projects = new Map();
    }

    /**
     * Creates a new project.
     * @param name The name of the project.
     * @param description The description of the project.
     * @returns The created project.
     */
    create(name: string, description: string): Project {
        if (!name) {
            throw new Error('Project name is required.');
        }
        const id = randomUUID();
        const newProject: Project = { id, name, description, memberIds: [] };
        this.projects.set(id, newProject);
        return newProject;
    }

    /**
     * Retrieves a project by its ID.
     * @param id The ID of the project.
     * @returns The project, or undefined if not found.
     */
    getById(id: string): Project | undefined {
        return this.projects.get(id);
    }

    /**
     * Retrieves all projects.
     * @returns An array of all projects.
     */
    getAll(): Project[] {
        return Array.from(this.projects.values());
    }

    /**
     * Updates an existing project.
     * @param id The ID of the project to update.
     * @param updates An object containing the fields to update (name, description).
     * @returns The updated project, or undefined if the project was not found.
     */
    update(id: string, updates: { name?: string; description?: string }): Project | undefined {
        const project = this.projects.get(id);
        if (project) {
            if (updates.name !== undefined) project.name = updates.name;
            if (updates.description !== undefined) project.description = updates.description;
            this.projects.set(id, project); 
            return project;
        }
        return undefined;
    }

    /**
     * Deletes a project by its ID.
     * @param id The ID of the project to delete.
     * @returns True if the project was deleted, false otherwise.
     */
    delete(id: string): boolean {
        return this.projects.delete(id);
    }

    /**
     * Adds a member to a project.
     * @param projectId The ID of the project.
     * @param memberId The ID of the user to add as a member.
     * @returns The updated project, or undefined if the project was not found.
     */
    addMember(projectId: string, memberId: string): Project | undefined {
        const project = this.projects.get(projectId);
        if (project) {
            if (!project.memberIds.includes(memberId)) {
                project.memberIds.push(memberId);
                this.projects.set(projectId, project);
            }
            return project;
        }
        return undefined;
    }

    /**
     * Removes a member from a project.
     * @param projectId The ID of the project.
     * @param memberId The ID of the user to remove from members.
     * @returns The updated project, or undefined if the project was not found.
     */
    removeMember(projectId: string, memberId: string): Project | undefined {
        const project = this.projects.get(projectId);
        if (project) {
            const initialLength = project.memberIds.length;
            project.memberIds = project.memberIds.filter(id => id !== memberId);
            if (project.memberIds.length < initialLength) {
                this.projects.set(projectId, project);
            }
            return project;
        }
        return undefined;
    }
}

export const projectService = new ProjectService();

import { randomUUID } from 'crypto';
import { eventBus } from '../event-bus';

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export interface Task {
    id: string;
    title: string;
    description: string;
    status: TaskStatus;
    assigneeId: string | null;
    projectId: string;
}

class TaskService {
    private tasks: Map<string, Task>;

    constructor() {
        this.tasks = new Map();
    }

    /**
     * Creates a new task.
     * @param title The title of the task.
     * @param description The description of the task.
     * @param projectId The ID of the project the task belongs to.
     * @returns The created task.
     */
    create(title: string, description: string, projectId: string): Task {
        if (!title || !projectId) {
            throw new Error('Title and Project ID are required to create a task.');
        }
        const id = randomUUID();
        const newTask: Task = { id, title, description, status: 'todo', assigneeId: null, projectId };
        this.tasks.set(id, newTask);
        return newTask;
    }

    /**
     * Retrieves a task by its ID.
     * @param id The ID of the task.
     * @returns The task, or undefined if not found.
     */
    getById(id: string): Task | undefined {
        return this.tasks.get(id);
    }

    /**
     * Retrieves all tasks for a given project.
     * @param projectId The ID of the project.
     * @returns An array of tasks belonging to the project.
     */
    getByProject(projectId: string): Task[] {
        return Array.from(this.tasks.values()).filter(task => task.projectId === projectId);
    }

    /**
     * Updates an existing task.
     * @param id The ID of the task to update.
     * @param updates An object containing the fields to update (title, description).
     * @returns The updated task, or undefined if the task was not found.
     */
    update(id: string, updates: { title?: string; description?: string }): Task | undefined {
        const task = this.tasks.get(id);
        if (task) {
            if (updates.title !== undefined) task.title = updates.title;
            if (updates.description !== undefined) task.description = updates.description;
            this.tasks.set(id, task);
            return task;
        }
        return undefined;
    }

    /**
     * Deletes a task by its ID.
     * @param id The ID of the task to delete.
     * @returns True if the task was deleted, false otherwise.
     */
    delete(id: string): boolean {
        return this.tasks.delete(id);
    }

    /**
     * Assigns a task to a user.
     * Publishes 'task.assigned' event.
     * @param taskId The ID of the task.
     * @param assigneeId The ID of the user to assign the task to.
     * @returns The updated task, or undefined if the task was not found.
     */
    assign(taskId: string, assigneeId: string): Task | undefined {
        const task = this.tasks.get(taskId);
        if (task) {
            task.assigneeId = assigneeId;
            this.tasks.set(taskId, task);
            eventBus.publish('task.assigned', { taskId: task.id, taskTitle: task.title, assigneeId: task.assigneeId });
            return task;
        }
        return undefined;
    }

    /**
     * Changes the status of a task.
     * Status transitions: 'todo' -> 'in-progress' -> 'done'.
     * Publishes 'task.statusChanged' event.
     * @param taskId The ID of the task.
     * @param newStatus The new status to set.
     * @returns The updated task, or undefined if the task was not found or transition is invalid.
     * @throws Error if the status transition is invalid.
     */
    changeStatus(taskId: string, newStatus: TaskStatus): Task | undefined {
        const task = this.tasks.get(taskId);
        if (task) {
            const oldStatus = task.status;
            if (oldStatus === newStatus) {
                return task; // No change needed
            }

            // Validate status transitions
            if (
                (oldStatus === 'todo' && newStatus === 'in-progress') ||
                (oldStatus === 'in-progress' && newStatus === 'done')
            ) {
                task.status = newStatus;
                this.tasks.set(taskId, task);
                eventBus.publish('task.statusChanged', { taskId: task.id, taskTitle: task.title, assigneeId: task.assigneeId, oldStatus, newStatus });
                return task;
            } else {
                throw new Error(`Invalid status transition from '${oldStatus}' to '${newStatus}' for task ${taskId}`);
            }
        }
        return undefined;
    }
}

export const taskService = new TaskService();

import { randomUUID } from 'crypto';
import { eventBus } from '../event-bus';

export interface Comment {
    id: string;
    taskId: string;
    authorId: string;
    body: string;
    createdAt: number; // Unix timestamp
}

class CommentService {
    private comments: Map<string, Comment>;

    constructor() {
        this.comments = new Map();
    }

    /**
     * Creates a new comment for a task.
     * Publishes 'comment.added' event.
     * @param taskId The ID of the task the comment belongs to.
     * @param authorId The ID of the user who authored the comment.
     * @param body The content of the comment.
     * @param taskTitle The title of the task (needed for event payload, passed by caller).
     * @param authorName The name of the author (needed for event payload, passed by caller).
     * @returns The created comment.
     */
    create(taskId: string, authorId: string, body: string, taskTitle: string, authorName: string): Comment {
        if (!taskId || !authorId || !body) {
            throw new Error('Task ID, Author ID, and comment body are required.');
        }
        const id = randomUUID();
        const newComment: Comment = {
            id,
            taskId,
            authorId,
            body,
            createdAt: Date.now(),
        };
        this.comments.set(id, newComment);
        eventBus.publish('comment.added', { commentId: newComment.id, taskId, taskTitle, authorId, authorName });
        return newComment;
    }

    /**
     * Retrieves all comments for a given task.
     * @param taskId The ID of the task.
     * @returns An array of comments belonging to the task.
     */
    getByTask(taskId: string): Comment[] {
        return Array.from(this.comments.values()).filter(comment => comment.taskId === taskId);
    }

    /**
     * Retrieves a comment by its ID.
     * @param id The ID of the comment.
     * @returns The comment, or undefined if not found.
     */
    getById(id: string): Comment | undefined {
        return this.comments.get(id);
    }

    /**
     * Deletes a comment by its ID.
     * @param id The ID of the comment to delete.
     * @returns True if the comment was deleted, false otherwise.
     */
    delete(id: string): boolean {
        return this.comments.delete(id);
    }
}

export const commentService = new CommentService();
